const _ = require("lodash");

class ContactValidator {
  static validContact = (phone) => {
    const count = this.validPhoneNumber(phone);
    return count 
  };
  static validPhoneNumber = (phone) => {
    let phone_regex = /\(?\d{3}\)?-? *\d{3}-? *-?\d{4}/;
    if (phone === null){
      return false;
    } else {
      return phone.match(phone_regex) !== null;
    }
  };

  static validate = function(contacts) {
    let bad_contacts = 0;
    const val_contacts = _.map(contacts, (contact) => {
      let phone = _.get(contact, ['Phone']);
      contact['valid'] = true;
      const validity= this.validContact(phone);
      if (!validity) {
        contact['valid'] = false;
        bad_contacts++;
      }
      return contact;
    })
    return { val_contacts: val_contacts, bad_contacts: bad_contacts }
  };

}

exports.main = ({ contacts }) => {
  return ContactValidator.validate(contacts);
}
